.create table test_results_silver_combined (Id: long, CommitsId: long, TestsId: long, SeverityId: int, Actual: string, Expected: string, Details: string, Passed: int, Date: datetime, Time: timespan)

// Create Functions to Combine
.create-or-alter function with (folder = "Combined Test Results") fnPQLintTestResultsToCombined() {
    pq_lint_test_results_silver
    | distinct Id, CommitsId, TestsId, SeverityId, Actual, Expected, Details, Passed, Date, Time
}

.create-or-alter function with (folder = "Combined Test Results") fnPBIRInspectorTestResultsToCombined() {
    pbir_inspector_test_results_silver
    | distinct Id, CommitsId, TestsId, SeverityId, Actual, Expected, Details, Passed, Date, Time
}

.create-or-alter function with (folder = "Combined Test Results") fnTabularEditorTestResultsToCombined() {
    tabular_editor_test_results_silver
    | distinct Id, CommitsId, TestsId, SeverityId, Actual, Expected, Details, Passed, Date, Time
}

// Hook up policies
.alter table test_results_silver_combined policy update
@'[{"IsEnabled": true,"Source": "pq_lint_test_results_silver","Query": "fnPQLintTestResultsToCombined()","IsTransactional": false,"PropagateIngestionProperties": false},{"IsEnabled": true,"Source": "pbir_inspector_test_results_silver","Query": "fnPBIRInspectorTestResultsToCombined()","IsTransactional": false,"PropagateIngestionProperties": false},{"IsEnabled": true,"Source": "tabular_editor_test_results_silver","Query": "fnTabularEditorTestResultsToCombined()","IsTransactional": false,"PropagateIngestionProperties": false}]'

#.drop materialized-view TestResults

.create materialized-view with (backfill=true) TestResults on table test_results_silver_combined
{
    test_results_silver_combined
    | summarize take_any(*) by Id, CommitsId, TestsId, SeverityId, Actual, Expected, Details, Passed, Date, Time
}

TestResults
| order by Date desc 

Commits
